(7384370, 1159013, 138253, '<td valign="top">DASHER! The rest of the sleigh team is looking for you; practice on the Toronto Ice Fields starts at 3, behind the National Igloo! ;)</td>', 'DASHER! The rest of the sleigh team is looking for you; practice on the Toronto Ice Fields starts at 3, behind the National Igloo! ;)', '2015-07-08 13:20:46.000000', NULL, 1),
(7384371, 1159280, 60173, '<td valign="top">I can''t say I really "get" this image, but there''s nothing that really bothers me about it. The colors are nice.</td>', 'I can''t say I really "get" this image, but there''s nothing that really bothers me about it. The colors are nice.', '2015-07-08 13:20:48.000000', NULL, 1),
